"""Public, recorded project evidence rendered without a backend."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PINN = 'https://github.com/muecke-math/Master-Amit-Amit/blob/b91b3aaace9229319ca4f3c85e90055be5766d0a/TensorDiffEq/examples/Allen-Cahn/'

def landslide_chart():
    rows=''.join(f'<div class="bar-row"><div class="bar-label"><span>{name}</span><strong>{score:.3f}</strong></div><div class="bar-track"><div class="bar-fill" style="width:{score*100}%"></div></div></div>' for name,score in [('Baseline UNet',.721),('RGB + height',.718),('UNet + augmentation + CE',.736),('UNet + augmentation + Lovász',.756),('Swin-UNet + augmentation + Lovász',.745)])
    return f'<div class="chart"><p class="eyebrow">Team report / F1 score</p><h3>Training choices, compared.</h3>{rows}<p>Scale: 0–1. Selected report results from a custom split using half the original training data. Collaborative results; not official challenge test scores.</p></div>'

def pinn_evidence():
    return f'''<section class="evidence-links"><h2>Explore the saved experiments</h2><p>The repository includes actual solution, residual and absolute-error figures from my Allen–Cahn experiments. These links point to the same archived commit so the evidence stays traceable.</p><div class="actions"><a class="textlink" href="{PINN}Baseline/train/AC_SA_baseline.png">Solution and prediction ↗</a><a class="textlink" href="{PINN}Baseline/train/AC_residual.png">Residual figure ↗</a><a class="textlink" href="{PINN}Baseline/train/AC_absolute_error.png">Absolute-error figure ↗</a></div><p class="fine">Associated <a href="{PINN}AC-SA-new.py">experiment script</a>: 50,000 collocation points, four 128-unit hidden layers, adaptive weights and periodic boundary conditions. No execution manifest ties the saved pixels to a specific run; these figures do not establish a final model ranking.</p></section>'''

def inspection_gallery():
    data=json.loads((ROOT/'assets/inspection/examples.json').read_text(encoding='utf-8'))
    panels=[]
    notes={'detected':'The anomalous image scores above the threshold and is correctly flagged.', 'missed':'The anomalous image falls just below the threshold. A visually plausible overlay does not guarantee a correct image-level decision.', 'false-alarm':'The dataset labels this image normal, but its score exceeds the threshold. This is an unnecessary reject.'}
    controls=''.join(f'<button type="button" data-example="{e["id"]}" aria-controls="example-{e["id"]}" aria-pressed="false">{e["outcome"]}</button>' for e in data['examples'])
    for e in data['examples']:
        key=e['id']
        panels.append(f'''<article id="example-{key}" data-example-panel="{key}" class="example-panel"><h3>{e['outcome']}</h3><div class="scoreline"><span>Score <strong>{e['score']:.6f}</strong></span><span>Threshold <strong>{e['threshold']:.6f}</strong></span><span>Label <strong>{'normal' if key=='false-alarm' else 'anomalous'}</strong></span></div><div class="evidence-pair"><figure><a href="../assets/inspection/{key}-input.jpg"><img src="../assets/inspection/{key}-input.jpg" width="1404" height="1070" loading="lazy" alt="Original VisA PCB2 image for the {e['outcome'].lower()} example"></a><figcaption>Original input · click to inspect full size</figcaption></figure><figure><a href="../assets/inspection/{key}-overlay.png"><img src="../assets/inspection/{key}-overlay.png" width="512" height="512" loading="lazy" alt="Cropped and resized qualitative anomaly overlay for the {e['outcome'].lower()} example"></a><figcaption>Board crop · 512 px qualitative overlay</figcaption></figure></div><p>{notes[key]}</p></article>''')
    return f'''<section id="recorded-examples" class="recorded-examples" aria-labelledby="examples-title"><p class="eyebrow">Recorded results / PCB2 crop 512</p><h2 id="examples-title">One model. Three outcomes.</h2><p>Browse a detected defect, a missed defect and a false alarm from the same development evaluation. These are saved predictions; no image upload or live inference is required.</p><div class="example-controls" hidden aria-label="Choose a recorded example">{controls}</div><div aria-live="polite">{''.join(panels)}</div><p class="fine">The decision is anomalous when score &gt; threshold; the score is not a probability. Input images and overlays have different coordinates because of cropping and resizing. Redness is a qualitative anomaly visualization, not a segmentation mask. These deliberately selected examples are not a representative sample.</p><p class="fine">Images: VisA / Amazon Science, Yang Zou and coauthors, <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Overlay modifications by Amit. <a href="../assets/inspection/ATTRIBUTION.md">Full attribution</a> · <a href="../assets/inspection/examples.json">Exact scores and provenance</a>.</p></section>'''
